insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006200', '$e^x(x-1)+C$', 'Escolha $u=x$ e $dv=e^x dx$, logo $du=dx$ e $v=e^x$. Por partes, $\int xe^x dx=xe^x-\int e^x dx=e^x(x-1)+C$.') on conflict do nothing;
