insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006203', '$e^{2x}(x/2-1/4)+C$', 'Com $u=x$ e $dv=e^{2x}dx$, temos $v=e^{2x}/2$. Subtraia $\frac12\int e^{2x}dx$ de $xe^{2x}/2$, obtendo $e^{2x}(x/2-1/4)+C$.') on conflict do nothing;
